{
  "kcs": [
    {
      "canonical_name": "数列极限",
      "aliases": ["序列极限"],
      "description": "描述数列无限趋近特定值的数学概念，用ε-N语言定义。"
    },
    {
      "canonical_name": "函数极限",
      "aliases": ["极限", "函数极限的ε-δ定义"],
      "description": "描述函数在某点附近趋近特定值的概念，包括左右极限。"
    },
    {
      "canonical_name": "无穷小量",
      "aliases": ["无穷小", "等价无穷小"],
      "description": "极限为零的变量，用于比较无穷小阶次与等价替换。"
    },
    {
      "canonical_name": "函数的连续性",
      "aliases": ["连续", "连续函数"],
      "description": "函数在某点极限等于函数值，闭区间上具有有界、最值、介值性质。"
    },
    {
      "canonical_name": "导数",
      "aliases": ["导数定义", "导函数", "瞬时变化率"],
      "description": "函数在某点变化率的极限，几何意义为切线斜率。"
    },
    {
      "canonical_name": "基本初等函数导数表",
      "aliases": ["导数表", "基本导数公式"],
      "description": "列出常数、幂、三角、指数、对数等函数的导数公式。"
    },
    {
      "canonical_name": "求导法则",
      "aliases": ["四则运算法则", "复合函数求导", "链式法则", "反函数求导"],
      "description": "用于求导的四则运算、复合函数与反函数的求导规则。"
    },
    {
      "canonical_name": "高阶导数",
      "aliases": ["高阶导", "n阶导数"],
      "description": "对函数多次求导得到的导数，表示变化率的变化率。"
    },
    {
      "canonical_name": "隐函数求导",
      "aliases": ["隐函数微分法"],
      "description": "对隐函数方程两边求导，解出导函数的方法。"
    },
    {
      "canonical_name": "罗尔定理",
      "aliases": ["Rolle定理"],
      "description": "若函数闭区间连续、开区间可导且端点值相等，则内有一点导数为零。"
    },
    {
      "canonical_name": "拉格朗日中值定理",
      "aliases": ["拉格朗日定理", "微分中值定理"],
      "description": "若函数闭区间连续、开区间可导，则存在点使导数等于端点斜率。"
    },
    {
      "canonical_name": "柯西中值定理",
      "aliases": ["柯西定理"],
      "description": "推广的拉格朗日中值定理，涉及两个函数的导数比值关系。"
    },
    {
      "canonical_name": "洛必达法则",
      "aliases": ["L'Hôpital法则", "洛必达规则"],
      "description": "在0/0或∞/∞型极限中，对分子分母分别求导再取极限的方法。"
    },
    {
      "canonical_name": "泰勒公式",
      "aliases": ["Taylor公式", "泰勒展开", "麦克劳林展开"],
      "description": "用多项式逼近函数的公式，含佩亚诺余项和拉格朗日余项。"
    },
    {
      "canonical_name": "不定积分",
      "aliases": ["原函数", "反导数"],
      "description": "导数的逆运算，表示函数的全体原函数集合。"
    },
    {
      "canonical_name": "基本积分表",
      "aliases": ["积分表", "基本积分公式"],
      "description": "列出幂、三角、指数、对数等函数的不定积分公式。"
    },
    {
      "canonical_name": "换元积分法",
      "aliases": ["代换法", "u-substitution"],
      "description": "通过变量代换简化积分计算的方法，包括第一类换元和第二类换元。"
    },
    {
      "canonical_name": "分部积分法",
      "aliases": ["分部积分公式"],
      "description": "将积分转化为另一积分的方法，适用于乘积形式函数的积分。"
    },
    {
      "canonical_name": "定积分",
      "aliases": ["黎曼积分"],
      "description": "函数在区间上黎曼和的极限，表示面积、路程等累积量。"
    },
    {
      "canonical_name": "牛顿-莱布尼茨公式",
      "aliases": ["微积分基本定理"],
      "description": "将定积分与原函数关联，用于计算定积分值。"
    },
    {
      "canonical_name": "定积分的应用",
      "aliases": ["积分应用"],
      "description": "利用定积分求面积、体积、弧长、功等几何与物理量。"
    }
  ],
